sp_widget.css:
/* ===================================
   HERO
=================================== */

.automed-hero{

    position:relative;

    overflow:hidden;

    border-radius:24px;

    padding:40px;

    color:#fff;

    background:linear-gradient(
        -45deg,
        #1B5E20,
        #2E7D32,
        #43A047,
        #66BB6A
    );

    background-size:400% 400%;

    animation:gradientMove 12s ease infinite;

    box-shadow:
        0 15px 35px rgba(0,0,0,.18);
}

@keyframes gradientMove{

    0%{
        background-position:0% 50%;
    }

    50%{
        background-position:100% 50%;
    }

    100%{
        background-position:0% 50%;
    }
}

/* ===================================
   CLOCK
=================================== */

.clock-bg{

    position:absolute;

    right:-80px;

    top:-50px;

    opacity:.12;
}

.clock-face{

    width:320px;

    height:320px;

    border:10px solid #fff;

    border-radius:50%;

    position:relative;
}

.hour-hand{

    position:absolute;

    width:6px;

    height:80px;

    background:white;

    left:50%;

    top:50%;

    border-radius:5px;

    transform-origin:bottom center;

    transform:
        translateX(-50%)
        translateY(-100%)
        rotate(45deg);
}

.minute-hand{

    position:absolute;

    width:4px;

    height:120px;

    background:white;

    left:50%;

    top:50%;

    transform-origin:bottom center;

    animation:rotateClock 20s linear infinite;
}

@keyframes rotateClock{

    from{

        transform:
        translateX(-50%)
        translateY(-100%)
        rotate(0deg);
    }

    to{

        transform:
        translateX(-50%)
        translateY(-100%)
        rotate(360deg);
    }
}

/* ===================================
   FLOATING PILLS
=================================== */

.pill{

    position:absolute;

    color:rgba(255,255,255,.18);

    font-size:32px;
}

.pill1{

    top:15%;

    left:8%;

    animation:floatPill 5s infinite;
}

.pill2{

    bottom:20%;

    right:20%;

    animation:floatPill 7s infinite;
}

.pill3{

    top:20%;

    right:10%;

    animation:floatPill 6s infinite;
}

@keyframes floatPill{

    0%{
        transform:translateY(0);
    }

    50%{
        transform:translateY(-15px);
    }

    100%{
        transform:translateY(0);
    }
}

/* ===================================
   HEALTHCARE TEAM
=================================== */

.health-icon{

    position:absolute;

    color:rgba(255,255,255,.10);
}

.doctor{

    top:10%;

    right:15%;

    font-size:90px;

    animation:floatHealth 7s infinite;
}

.caregiver{

    top:50%;

    right:28%;

    font-size:80px;

    animation:floatHealth 8s infinite;
}

.patient{

    bottom:10%;

    right:12%;

    font-size:85px;

    animation:floatHealth 6s infinite;
}

.hospital{

    top:25%;

    left:40%;

    font-size:70px;

    animation:floatHealth 9s infinite;
}

@keyframes floatHealth{

    0%{
        transform:translateY(0);
    }

    50%{
        transform:translateY(-15px);
    }

    100%{
        transform:translateY(0);
    }
}

/* ===================================
   CONTENT
=================================== */

.automed-hero-inner{

    position:relative;

    z-index:2;
}

.portal-badge{

    display:inline-block;

    padding:8px 16px;

    border-radius:30px;

    background:rgba(255,255,255,.18);

    backdrop-filter:blur(10px);

    margin-bottom:20px;
}

.portal-badge i{

    margin-right:5px;
}

.automed-hero h1{

    margin:0 0 15px;

    font-size:42px;

    font-weight:700;
}

.hero-subtitle{

    font-size:20px;

    margin-bottom:10px;
}

.hero-description{

    font-size:16px;

    opacity:.95;

    margin-bottom:30px;
}

/* ===================================
   STATS
=================================== */

.hero-stats{

    display:flex;

    gap:15px;
}

.stat-box{

    background:rgba(255,255,255,.12);

    backdrop-filter:blur(12px);

    border:1px solid rgba(255,255,255,.15);

    padding:15px 25px;

    border-radius:15px;

    transition:.3s;
}

.stat-box:hover{

    transform:translateY(-5px);

    background:rgba(255,255,255,.20);
}

.stat-number{

    display:block;

    font-size:28px;

    font-weight:700;
}

.stat-label{

    font-size:13px;
}

/* ===================================
   MOBILE
=================================== */

@media(max-width:768px){

    .automed-hero{

        padding:25px;
    }

    .automed-hero h1{

        font-size:28px;
    }

    .hero-stats{

        flex-direction:column;
    }

    .clock-face{

        width:180px;

        height:180px;
    }

    .health-icon{

        display:none;
    }
}

sp_widget.script:
(function() {

    data.user_name = gs.getUser().getFirstName();

    var hour = parseInt(
        new GlideDateTime()
        .getLocalTime()
        .getByFormat("HH")
    );

    if(hour < 12)
        data.greeting = "Good Morning";
    else if(hour < 17)
        data.greeting = "Good Afternoon";
    else
        data.greeting = "Good Evening";

    // Replace these with actual GlideRecord counts later
    data.due_today = 5;
    data.patient_count = 12;

})();
